  5	export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';
  6	
  7	/** One row of the `jobs` table, as read by either process. */
  8	export interface JobRow {
  9	  seq: number;
 10	  id: string;
 11	  status: JobStatus;
 12	  input: string;
 13	  steps: number;
 14	  fail_attempts: number;
 15	  attempts: number;
 16	  completed: number;
 17	  output: string | null;
 18	  error: string | null;
 19	  available_at: number;
 20	  created_at: string;
 21	  updated_at: string;
 22	}
 23	
 24	const SCHEMA = `
 25	CREATE TABLE IF NOT EXISTS jobs (
 26	  seq          INTEGER PRIMARY KEY AUTOINCREMENT,
 27	  id           TEXT NOT NULL UNIQUE,
 28	  status       TEXT NOT NULL,
 29	  input        TEXT NOT NULL,
 30	  steps        INTEGER NOT NULL,
 31	  fail_attempts INTEGER NOT NULL,
 32	  attempts     INTEGER NOT NULL DEFAULT 0,
 33	  completed    INTEGER NOT NULL DEFAULT 0,
 34	  output       TEXT,
 35	  error        TEXT,
 36	  available_at INTEGER NOT NULL DEFAULT 0,
 37	  created_at   TEXT NOT NULL,
 38	  updated_at   TEXT NOT NULL
 39	);
 40	CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
 41	CREATE TABLE IF NOT EXISTS idempotency (
 42	  key     TEXT PRIMARY KEY,
 43	  payload TEXT NOT NULL,
 44	  job_id  TEXT NOT NULL
 45	);
 46	CREATE TABLE IF NOT EXISTS heartbeats (
 47	  name TEXT PRIMARY KEY,
 48	  at   INTEGER NOT NULL
 49	);
 50	`;
 51	
 52	/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
 53	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
 54	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
 55	  const db = new DatabaseSync(path);
 56	  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
 57	  // open the same database at once, so the loser must wait rather than fail.
 58	  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
 59	  db.exec(SCHEMA);
 60	  return db;
 61	}
 62	
 63	export function nowIso(): string {
 64	  return new Date().toISOString();
 65	}
 66	
 67	/** Converts a row to the public job JSON shape. */
 68	export function toJob(r: JobRow) {
 69	  return {
 70	    id: r.id,
 71	    status: r.status,
 72	    input: r.input,
 73	    steps: r.steps,
 74	    failAttempts: r.fail_attempts,
 75	    attempts: r.attempts,
 76	    progress: { completed: r.completed, total: r.steps },
 77	    result: r.status === 'completed' && r.output !== null ? { output: r.output } : null,
 78	    error: r.status === 'failed' ? r.error : null,
 79	    createdAt: r.created_at,
 80	    updatedAt: r.updated_at,
 81	  };
 82	}
  1	import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
  2	import { randomUUID } from 'node:crypto';
  3	import { readFileSync } from 'node:fs';
  4	import { nowIso, openDatabase, toJob, type JobRow } from './db.ts';
  5	import { validateSubmission, type FieldError, type Submission } from './validation.ts';
  6	
  7	const db = openDatabase();
  8	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
  9	
 10	/** The worker counts as up only if its heartbeat is younger than this. */
 11	const WORKER_FRESH_MS = 3000;
 12	const MAX_BODY_BYTES = 64 * 1024;
 13	
 14	const stmts = {
 15	  allJobs: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
 16	  jobById: db.prepare('SELECT * FROM jobs WHERE id = ?'),
 17	  idempotencyByKey: db.prepare('SELECT payload, job_id FROM idempotency WHERE key = ?'),
 18	  insertJob: db.prepare(
 19	    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, output, error, available_at, created_at, updated_at)
 20	     VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
 21	  ),
 22	  insertIdempotency: db.prepare('INSERT INTO idempotency (key, payload, job_id) VALUES (?, ?, ?)'),
 23	  workerHeartbeat: db.prepare("SELECT at FROM heartbeats WHERE name = 'worker'"),
 24	};
 25	
 26	function send(res: ServerResponse, status: number, body: unknown): void {
 27	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
 28	  res.end(JSON.stringify(body));
 29	}
 30	
 31	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
 32	  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
 33	  if (fields) error.fields = fields;
 34	  send(res, status, { error });
 35	}
 36	
 37	function workerUp(): boolean {
 38	  const row = stmts.workerHeartbeat.get() as { at: number } | undefined;
 39	  return row !== undefined && Date.now() - row.at < WORKER_FRESH_MS;
 40	}
 41	
 42	function readBody(req: IncomingMessage): Promise<{ body: string; bodyTooLarge: boolean }> {
 43	  return new Promise((resolve, reject) => {
 44	    const chunks: Buffer[] = [];
 45	    let size = 0;
 46	    let bodyTooLarge = false;
 47	    req.on('data', (chunk: Buffer) => {
 48	      size += chunk.length;
 49	      if (size > MAX_BODY_BYTES) bodyTooLarge = true;
 50	      else chunks.push(chunk);
 51	    });
 52	    req.on('end', () => resolve({ body: Buffer.concat(chunks).toString('utf8'), bodyTooLarge }));
 53	    req.on('error', reject);
 54	  });
 55	}
 56	
 57	type SubmitResult = { kind: 'created' | 'replayed'; job: JobRow } | { kind: 'conflict' };
 58	
 59	/**
 60	 * Creates a job, or resolves an Idempotency-Key. The lookup and insert run in one immediate
 61	 * transaction, so a key can never create two jobs, including across restarts.
 62	 */
 63	function submit(s: Submission, key: string | undefined): SubmitResult {
 64	  const payload = JSON.stringify([s.input, s.steps, s.failAttempts]);
 65	  db.exec('BEGIN IMMEDIATE');
 66	  try {
 67	    if (key !== undefined) {
 68	      const prior = stmts.idempotencyByKey.get(key) as { payload: string; job_id: string } | undefined;
 69	      if (prior) {
 70	        db.exec('COMMIT');
 71	        if (prior.payload !== payload) return { kind: 'conflict' };
 72	        return { kind: 'replayed', job: stmts.jobById.get(prior.job_id) as unknown as JobRow };
 73	      }
 74	    }
 75	    const id = randomUUID();
 76	    const now = nowIso();
 77	    stmts.insertJob.run(id, s.input, s.steps, s.failAttempts, now, now);
 78	    if (key !== undefined) stmts.insertIdempotency.run(key, payload, id);
 79	    db.exec('COMMIT');
 80	    return { kind: 'created', job: stmts.jobById.get(id) as unknown as JobRow };
 81	  } catch (e) {
 82	    db.exec('ROLLBACK');
 83	    throw e;
 84	  }
 85	}
