 87	async function createJobRoute(req: IncomingMessage, res: ServerResponse): Promise<void> {
 88	  const { body, bodyTooLarge } = await readBody(req);
 89	  const v = validateSubmission({
 90	    contentType: req.headers['content-type'],
 91	    body,
 92	    bodyTooLarge,
 93	    idempotencyKey: req.headers['idempotency-key'],
 94	  });
 95	  if (!v.ok) {
 96	    sendError(res, 400, 'invalid_request', 'The request is invalid.', v.fields);
 97	    return;
 98	  }
 99	  const result = submit(v.value, v.key);
100	  if (result.kind === 'conflict') {
101	    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
102	    return;
103	  }
104	  send(res, result.kind === 'created' ? 201 : 200, toJob(result.job));
105	}
