107	const ROUTES: Array<{ pattern: RegExp; methods: string[] }> = [
108	  { pattern: /^\/health$/, methods: ['GET'] },
109	  { pattern: /^\/$/, methods: ['GET'] },
110	  { pattern: /^\/api\/jobs$/, methods: ['GET', 'POST'] },
111	  { pattern: /^\/api\/jobs\/[^/]+$/, methods: ['GET'] },
112	];
113	
114	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
115	  const method = req.method ?? 'GET';
116	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
117	
118	  const route = ROUTES.find((r) => r.pattern.test(pathname));
119	  if (!route) {
120	    sendError(res, 404, 'not_found', 'No such route.');
121	    return;
122	  }
123	  if (!route.methods.includes(method)) {
124	    res.setHeader('Allow', route.methods.join(', '));
125	    sendError(res, 405, 'method_not_allowed', `${method} is not allowed on this route.`);
126	    return;
127	  }
128	
129	  if (pathname === '/health') {
130	    send(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
131	    return;
132	  }
133	  if (pathname === '/') {
134	    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
135	    res.end(uiHtml);
136	    return;
137	  }
138	  if (pathname === '/api/jobs') {
139	    if (method === 'POST') return createJobRoute(req, res);
140	    const rows = stmts.allJobs.all() as unknown as JobRow[];
141	    send(res, 200, { jobs: rows.map(toJob) });
142	    return;
143	  }
144	
145	  let id: string;
146	  try {
147	    id = decodeURIComponent(pathname.slice('/api/jobs/'.length));
148	  } catch {
149	    sendError(res, 404, 'not_found', 'No job with that id.');
150	    return;
151	  }
152	  const row = stmts.jobById.get(id) as unknown as JobRow | undefined;
153	  if (!row) {
154	    sendError(res, 404, 'not_found', 'No job with that id.');
155	    return;
156	  }
157	  send(res, 200, toJob(row));
158	}
159	
160	const server = createServer((req, res) => {
161	  handle(req, res).catch((e: unknown) => {
162	    console.error('request failed:', e);
163	    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
164	    else res.end();
165	  });
166	});
167	
168	const port = Number(process.env.PORT ?? 3000);
169	server.listen(port, () => console.log(`server listening on ${port}`));
170	
171	function shutdown(): void {
172	  server.close(() => {
173	    db.close();
174	    process.exit(0);
175	  });
176	  server.closeAllConnections();
177	}
178	process.on('SIGTERM', shutdown);
179	process.on('SIGINT', shutdown);
  1	import { setTimeout as sleep } from 'node:timers/promises';
  2	import { nowIso, openDatabase, type JobRow } from './db.ts';
  3	
  4	const STEP_MS = 100;
  5	const POLL_MS = 200;
  6	const HEARTBEAT_MS = 1000;
  7	const RETRY_DELAY_MS = 500;
  8	const MAX_ATTEMPTS = 3;
  9	
 10	const db = openDatabase();
 11	let stopping = false;
 12	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
 13	  process.on(signal, () => {
 14	    stopping = true;
 15	  });
 16	}
 17	
 18	const stmts = {
 19	  heartbeat: db.prepare(
 20	    "INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at",
 21	  ),
 22	  // Only one worker runs at a time, so any job still 'running' was left behind by a dead worker.
 23	  requeueInterrupted: db.prepare(
 24	    "UPDATE jobs SET status = 'queued', completed = 0, updated_at = ? WHERE status = 'running'",
 25	  ),
 26	  nextQueued: db.prepare(
 27	    "SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1",
 28	  ),
 29	  startAttempt: db.prepare(
 30	    "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
 31	  ),
 32	  progress: db.prepare('UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ?'),
 33	  complete: db.prepare(
 34	    "UPDATE jobs SET status = 'completed', completed = steps, output = ?, updated_at = ? WHERE id = ?",
 35	  ),
 36	  requeue: db.prepare(
 37	    "UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE id = ?",
 38	  ),
 39	  fail: db.prepare(
 40	    "UPDATE jobs SET status = 'failed', completed = 0, error = 'transient failure', updated_at = ? WHERE id = ?",
 41	  ),
 42	};
 43	
 44	function beat(): void {
 45	  stmts.heartbeat.run(Date.now());
 46	}
 47	
 48	/** Runs one processing attempt. The attempt counter was already incremented by the caller. */
 49	async function runAttempt(job: JobRow, attempt: number): Promise<void> {
 50	  if (attempt <= job.fail_attempts) {
 51	    // Simulated transient failure: fails at the first step, before any progress.
 52	    await sleep(STEP_MS);
 53	    if (attempt >= MAX_ATTEMPTS) stmts.fail.run(nowIso(), job.id);
 54	    else stmts.requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
 55	    return;
 56	  }
 57	
 58	  for (let step = 1; step <= job.steps; step++) {
 59	    await sleep(STEP_MS);
 60	    if (stopping) {
 61	      // Clean shutdown: hand the job back so it is not stuck in 'running'.
 62	      stmts.requeue.run(0, nowIso(), job.id);
 63	      return;
 64	    }
 65	    stmts.progress.run(step, nowIso(), job.id);
 66	  }
 67	  stmts.complete.run(job.input.toUpperCase(), nowIso(), job.id);
 68	}
 69	
 70	const recovered = stmts.requeueInterrupted.run(nowIso()).changes;
 71	if (recovered) console.log(`re-queued ${recovered} interrupted job(s)`);
 72	beat();
 73	const heartbeatTimer = setInterval(beat, HEARTBEAT_MS);
 74	
 75	console.log('worker started');
 76	while (!stopping) {
 77	  const job = stmts.nextQueued.get(Date.now()) as unknown as JobRow | undefined;
 78	  if (!job) {
 79	    await sleep(POLL_MS);
 80	    continue;
 81	  }
 82	  const attempt = job.attempts + 1;
 83	  stmts.startAttempt.run(nowIso(), job.id);
 84	  await runAttempt(job, attempt);
 85	}
 86	
 87	clearInterval(heartbeatTimer);
 88	db.close();
 89	console.log('worker stopped');
  1	export interface FieldError {
  2	  field: string;
  3	  message: string;
  4	}
  5	
  6	export interface Submission {
  7	  input: string;
  8	  steps: number;
  9	  failAttempts: number;
 10	}
 11	
 12	export type Validation =
 13	  | { ok: true; value: Submission; key: string | undefined }
 14	  | { ok: false; fields: FieldError[] };
 15	
 16	const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
 17	const JSON_CONTENT_TYPE = /^application\/json\s*(;.*)?$/i;
 18	const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
 19	
 20	export interface RawSubmission {
 21	  contentType: string | undefined;
 22	  body: string;
 23	  bodyTooLarge: boolean;
 24	  idempotencyKey: string | string[] | undefined;
 25	}
 26	
 27	function isPlainObject(v: unknown): v is Record<string, unknown> {
 28	  return typeof v === 'object' && v !== null && !Array.isArray(v);
 29	}
 30	
 31	function integerIn(v: unknown, min: number, max: number): boolean {
 32	  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
 33	}
 34	
 35	/** Validates a POST /api/jobs request. Defaults are applied to optional numeric fields. */
 36	export function validateSubmission(raw: RawSubmission): Validation {
 37	  const fields: FieldError[] = [];
 38	  let key: string | undefined;
 39	  if (raw.idempotencyKey !== undefined) {
 40	    if (typeof raw.idempotencyKey === 'string' && KEY_RE.test(raw.idempotencyKey)) key = raw.idempotencyKey;
 41	    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
 42	  }
 43	
 44	  let value: Submission | undefined;
 45	  if (raw.bodyTooLarge) {
 46	    fields.push({ field: 'body', message: 'request body is too large' });
 47	  } else if (!raw.contentType || !JSON_CONTENT_TYPE.test(raw.contentType.trim())) {
 48	    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
 49	  } else {
 50	    let parsed: unknown;
 51	    try {
 52	      parsed = JSON.parse(raw.body);
 53	    } catch {
 54	      parsed = undefined;
 55	      fields.push({ field: 'body', message: 'body is not valid JSON' });
 56	    }
 57	    if (parsed !== undefined) {
 58	      if (!isPlainObject(parsed)) fields.push({ field: 'body', message: 'body must be a JSON object' });
 59	      else value = validateFields(parsed, fields);
 60	    }
 61	  }
 62	
 63	  if (fields.length > 0 || value === undefined) return { ok: false, fields };
 64	  return { ok: true, value, key };
 65	}
 66	
 67	function validateFields(obj: Record<string, unknown>, fields: FieldError[]): Submission | undefined {
 68	  for (const k of Object.keys(obj)) {
 69	    if (!ALLOWED_FIELDS.has(k)) fields.push({ field: k, message: 'unknown field' });
 70	  }
 71	
 72	  const { input, steps = 5, failAttempts = 0 } = obj as Record<string, unknown>;
 73	  let ok = true;
 74	
 75	  if (input === undefined) {
 76	    fields.push({ field: 'input', message: 'is required' });
 77	    ok = false;
 78	  } else if (typeof input !== 'string') {
 79	    fields.push({ field: 'input', message: 'must be a string' });
 80	    ok = false;
 81	  } else if (input.length < 1 || input.length > 1000) {
 82	    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
 83	    ok = false;
 84	  } else if (input.trim().length === 0) {
 85	    fields.push({ field: 'input', message: 'must not be only whitespace' });
 86	    ok = false;
 87	  }
 88	
 89	  if (!integerIn(steps, 1, 20)) {
 90	    fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
 91	    ok = false;
 92	  }
 93	  if (!integerIn(failAttempts, 0, 5)) {
 94	    fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
 95	    ok = false;
 96	  }
 97	
 98	  if (!ok) return undefined;
 99	  return { input: input as string, steps: steps as number, failAttempts: failAttempts as number };
100	}
